from itertools import permutations
class Solution:
    def minimumTotalPrice(self, prices: list[int], discounts: list[int]) -> float:
        n, m = len(prices), len(discounts)
        best = float(sum(prices))
        for perm in permutations(range(n), min(n, m)):
            total = sum(prices)
            for j, i in enumerate(perm):
                total -= prices[i] * discounts[j] / 100
            best = min(best, total)
        return best

