class Solution {
public:
    double minimumTotalPrice(vector<int>& prices, vector<int>& discounts) {
        int n = prices.size(), m = discounts.size(), k = min(n, m);
        vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
        double best = accumulate(prices.begin(), prices.end(), 0.0);
        vector<int> sel(k); 
        function<void(int,int)> rec = [&](int pos, int start) {
            if (pos == k) {
                double total = accumulate(prices.begin(), prices.end(), 0.0);
                for (int j = 0; j < k; j++) total -= prices[sel[j]] * discounts[j] / 100.0;
                best = min(best, total);
                return;
            }
            for (int i = start; i < n; i++) { sel[pos] = idx[i]; rec(pos + 1, i + 1); }
        };
        rec(0, 0);
        return best;
    }
};

