class Solution {
    double best;
    public double minimumTotalPrice(int[] prices, int[] discounts) {
        best = Arrays.stream(prices).sum();
        int k = Math.min(prices.length, discounts.length);
        dfs(prices, discounts, new int[k], 0, 0);
        return best;
    }
    private void dfs(int[] p, int[] d, int[] sel, int pos, int start) {
        if (pos == sel.length) {
            double total = Arrays.stream(p).sum();
            for (int j = 0; j < sel.length; j++) total -= p[sel[j]] * d[j] / 100.0;
            best = Math.min(best, total);
            return;
        }
        for (int i = start; i < p.length; i++) { sel[pos] = i; dfs(p, d, sel, pos + 1, i + 1); }
    }
}

