var minimumTotalPrice = function(prices, discounts) {
    const k = Math.min(prices.length, discounts.length);
    let best = prices.reduce((a, b) => a + b, 0);
    const sel = [];
    const dfs = (start) => {
        if (sel.length === k) {
            let total = prices.reduce((a, b) => a + b, 0);
            sel.forEach((i, j) => total -= prices[i] * discounts[j] / 100);
            best = Math.min(best, total);
            return;
        }
        for (let i = start; i < prices.length; i++) { sel.push(i); dfs(i + 1); sel.pop(); }
    };
    dfs(0);
    return best;
};

