class Solution {
    public double minimumTotalPrice(int[] prices, int[] discounts) {
        Integer[] pr = Arrays.stream(prices).boxed().toArray(Integer[]::new);
        Integer[] di = Arrays.stream(discounts).boxed().toArray(Integer[]::new);
        Arrays.sort(pr, (a, b) -> b - a);
        Arrays.sort(di, (a, b) -> b - a);
        double total = 0;
        for (int i = 0; i < pr.length; i++)
            total += i < di.length ? pr[i] * (100 - di[i]) / 100.0 : pr[i];
        return total;
    }
}

